import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[] sl = new int[52];
        sl[0] = 1;
        for (int i = 1; i <= 51; i++) {
            sl[i] = sl[i - 1] + (1 << i);
        }

        int h = sc.nextInt();
        int n = sc.nextInt();

        n = n + sl[h - 1];
        int[] sequence = new int[52];
        int seqLen = 1;
        sequence[0] = n;

        while (n > 1) {
            n /= 2;
            sequence[seqLen++] = n;
        }

        int total = 0;
        int current = 1;
        boolean flip = false;

        while (current != sequence[0]) {
            int[] tempList = new int[h + 2];
            int temp = current;
            for (int i = 0; i < h; i++) {
                tempList[i] = temp;
                if (!flip) {
                    temp *= 2;
                } else {
                    temp = temp * 2 + 1;
                }
                flip = !flip;
            }
            if (temp == sequence[0]) {
                total += h;
                break;
            }
            tempList[h] = temp;
            // reverse tempList
            for (int i = 0; i < h / 2; i++) {
                int tmp = tempList[i];
                tempList[i] = tempList[h - 1 - i];
                tempList[h - 1 - i] = tmp;
            }
            boolean found = false;
            for (int i = 1; i <= h; i++) {
                if (sequence[i] == tempList[i - 1]) {
                    total += sl[i - 1] + h - i + 1;
                    h = i - 1;
                    current = tempList[i - 1];
                    if (current == tempList[i - 1] * 2) {
                        current = tempList[i - 1] * 2 + 1;
                        flip = false;
                    } else {
                        current = tempList[i - 1] * 2;
                        flip = true;
                    }
                    found = true;
                    break;
                }
            }
            if (!found) {
                // If no match found, break to prevent infinite loop
                break;
            }
        }
        System.out.println(total);
        sc.close();
    }
}
